# Writes the sheep-dog meadow's hedra command files and its grass texture:
#   ground.txt + textures/grass.png, fence.txt (the meadow's fence and the pen), gate.txt, tree.txt,
#   rock.txt, pond.txt, hay.txt, trough.txt.
# Run from models/env: /usr/bin/python3 make_env.py. Up Z, front -Y (hedra); world x = hedra x,
# world z = -hedra y. Colours are exact DawnBringer 16 ramp steps (sRGB 0..1).
import random
from PIL import Image

def rgb(h):
    h = h.lstrip("#")
    return tuple(int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))

def col(h, emit=False):
    r, g, b = rgb(h)
    return f"--base-color {r:.3f} {g:.3f} {b:.3f}"

# --- the play area (world metres; the game.as constants match these)
X0, X1, Z0, Z1 = -6.4, 6.4, -4.2, 4.4          # the meadow's fence
PX0, PZ1 = 3.0, -1.6                             # the pen: x PX0..X1, z Z0..PZ1
GATE0, GATE1 = 3.7, 5.5                          # the pen's gate opening along z = PZ1

def box(name, x, z, y, sx, sz, sy, mat):
    """a box centred at world (x, y, z), sizes along world x, z, y"""
    return [f"add mesh cube --name {name} --size 1 --location {x:.3f} {-z:.3f} {y:.3f}",
            f"scale {sx:.3f} {sz:.3f} {sy:.3f}", "apply --scale", f"material assign {mat}"]

def write(name, lines):
    open(name, "w").write("\n".join(lines) + "\n")

# ---------------------------------------------------------------- ground + grass texture
random.seed(5)
TW, TH = 64, 52                                   # 16 x 13 m: 0.25 m a texel (~3.5 splats)
G0, G1, G2 = "#346524", "#6daa2c", "#dad45e"
img = Image.new("RGB", (TW, TH), rgb_i := tuple(int(c * 255) for c in rgb(G1)))
px = img.load()
def put(x, y, h):
    px[x % TW, y % TH] = tuple(int(c * 255) for c in rgb(h))
for _ in range(18):                               # darker tufts: 2 x 2 to 3 x 2 clumps
    x, y = random.randrange(TW), random.randrange(TH)
    for dx in range(random.choice((2, 3))):
        for dy in range(2):
            put(x + dx, y + dy, G0)
for _ in range(46):                               # flowers: a yellow texel pair
    x, y = random.randrange(TW), random.randrange(TH)
    put(x, y, G2)
    put(x + random.choice((0, 1)), y + 1, G2)
img.save("textures/grass.png")
write("ground.txt", [
    "# The meadow: one 16 x 13 m plane, grass with dark tufts and yellow flowers painted in a",
    "# palette-exact 64 x 52 texture (0.25 m a texel). Generated by make_env.py. Up Z.",
    "new",
    "add mesh grid --name Ground --size 1 --x-subdivisions 8 --y-subdivisions 8 --location 0 0 0",
    "scale 16 13 1", "apply --scale",
    "material new Grass --base-color 1 1 1",
    "material assign Grass",
    "active Ground", "mode edit", "select all", "uv project-from-view top --scale-to-bounds", "mode object",
    "material texture Grass base-color textures/grass.png",
    "shade flat", "export ground.glb"])

# ---------------------------------------------------------------- fence + pen
L = ["# The meadow's fence (x -6.4..6.4, z -4.2..4.4) and the pen in its back-right corner",
     "# (x 3.0..6.4, z -4.2..-1.6) with a gate gap at x 3.7..5.5. Posts 0.14 m, rails 0.1 x 0.08 m",
     "# (exaggerated for the splats). Generated by make_env.py. Up Z.", "new",
     f"material new Wood {col('#854c30')} --no-slot", f"material new Post {col('#d2aa99')} --no-slot"]
n = [0]
def run(a, b, along_x, fixed, gap=None):
    """posts and two rails from a to b along x (z = fixed) or along z (x = fixed)"""
    import math
    length = b - a
    k = max(1, round(length / 1.1))
    pts = [a + length * i / k for i in range(k + 1)]
    for p in pts:
        if gap and gap[0] + 0.05 < p < gap[1] - 0.05:
            continue
        n[0] += 1
        x, z = (p, fixed) if along_x else (fixed, p)
        L.extend(box(f"P{n[0]}", x, z, 0.36, 0.14, 0.14, 0.72, "Post"))
    segs = [(a, b)] if not gap else [(a, gap[0]), (gap[1], b)]
    for s0, s1 in segs:
        for h in (0.28, 0.56):
            n[0] += 1
            c, ln = (s0 + s1) / 2, s1 - s0
            if along_x:
                L.extend(box(f"R{n[0]}", c, fixed, h, ln, 0.08, 0.1, "Wood"))
            else:
                L.extend(box(f"R{n[0]}", fixed, c, h, 0.08, ln, 0.1, "Wood"))
run(X0, X1, True, Z0)            # back
run(X0, X1, True, Z1)            # front
run(Z0, Z1, False, X0)           # left
run(Z0, Z1, False, X1)           # right
run(PX0, X1, True, PZ1, gap=(GATE0, GATE1))   # the pen's front, with the gate gap
run(Z0, PZ1, False, PX0)         # the pen's left side
L += ["select all", "active P1", "join", "rename P1 Fence", "shade flat", "export fence.glb"]
write("fence.txt", L)

# ---------------------------------------------------------------- the gate (a game bone: swings shut on a win)
write("gate.txt", [
    "# The pen's gate: a red panel 1.8 m long hinged at its RIGHT end (origin at the hinge), lying",
    "# along -X when shut. Two rails, a diagonal brace, end posts. Generated by make_env.py. Up Z.", "new",
    f"material new Gate {col('#d04648')} --no-slot",
    *box("G1", -0.9, 0, 0.28, 1.8, 0.08, 0.1, "Gate"),
    *box("G2", -0.9, 0, 0.56, 1.8, 0.08, 0.1, "Gate"),
    *box("G3", -0.08, 0, 0.36, 0.12, 0.1, 0.62, "Gate"),
    *box("G4", -1.72, 0, 0.36, 0.12, 0.1, 0.62, "Gate"),
    "add mesh cube --name G5 --size 1 --location -0.9 0 0.42", "scale 1.7 0.07 0.09", "apply --scale",
    "set rotation 0 -14 0", "apply --rotation", "material assign Gate",
    "select all", "active G1", "join", "rename G1 Gate", "shade flat", "export gate.glb"])

# ---------------------------------------------------------------- tree, rock, pond, hay, trough
write("tree.txt", [
    "# A round meadow tree: a 6-sided trunk, two faceted crowns. 2.6 m tall. Up Z.", "new",
    f"material new Bark {col('#854c30')} --no-slot", f"material new Leaves {col('#6daa2c')} --no-slot",
    "add mesh cylinder --name Trunk --vertices 6 --radius 0.16 --depth 1.2 --location 0 0 0.6", "material assign Bark",
    "add mesh ico-sphere --name Crown --subdivisions 1 --radius 0.95 --location 0 0 1.7", "material assign Leaves",
    "add mesh ico-sphere --name Crown2 --subdivisions 1 --radius 0.6 --location 0.35 -0.2 2.3", "material assign Leaves",
    "mode edit", "select all", "randomize --amount 0.06 --seed 3", "mode object",
    "select all", "shade flat", "export tree.glb"])
write("rock.txt", [
    "# A grey field stone: a jittered, squashed icosahedron, 1.0 x 0.8 x 0.5 m. Up Z.", "new",
    "add mesh ico-sphere --name Rock --subdivisions 1 --radius 0.5 --location 0 0 0.16",
    "scale 1.0 0.8 0.6", "apply --scale", "mode edit", "select all", "randomize --amount 0.07 --seed 4", "mode object",
    f"material new Stone {col('#757161')}", "material assign Stone", "shade flat", "export rock.glb"])
write("pond.txt", [
    "# A pond: a 10-sided water disc (r 1.3) 4 cm under the grass in a ring of grey stones. Up Z.", "new",
    f"material new Water {col('#597dce')} --no-slot", f"material new Stone {col('#8595a1')} --no-slot",
    "add mesh circle --name Water --vertices 10 --radius 1.3 --cap-fill triangle-fan --location 0 0 0.02",
    "material assign Water",
    *[l for i in range(10) for l in (
        f"add mesh ico-sphere --name S{i} --subdivisions 1 --radius 0.24 --location "
        f"{1.42 * __import__('math').cos(i * 0.6283 + 0.3):.3f} {1.42 * __import__('math').sin(i * 0.6283 + 0.3):.3f} 0.06",
        "scale 1.2 1.0 0.6", "apply --scale", "material assign Stone")],
    "select all", "shade flat", "export pond.glb"])
write("hay.txt", [
    "# A hay bale: an 8-sided drum on its side, 0.9 m long, r 0.4. Up Z.", "new",
    f"material new Hay {col('#dad45e')}",
    "add mesh cylinder --name Hay --vertices 8 --radius 0.4 --depth 0.9 --location 0 0 0.4 --rotation 0 90 0",
    "apply --rotation", "material assign Hay", "shade flat", "export hay.glb"])
write("trough.txt", [
    "# A water trough: a wooden box 1.2 x 0.5 x 0.4 m with water inside. Up Z.", "new",
    f"material new Wood {col('#854c30')} --no-slot", f"material new Water {col('#6dc2ca')} --no-slot",
    *box("A", 0, 0.2, 0.2, 1.2, 0.08, 0.4, "Wood"), *box("B", 0, -0.2, 0.2, 1.2, 0.08, 0.4, "Wood"),
    *box("C", 0.56, 0, 0.2, 0.08, 0.48, 0.4, "Wood"), *box("D", -0.56, 0, 0.2, 0.08, 0.48, 0.4, "Wood"),
    *box("E", 0, 0, 0.3, 1.04, 0.32, 0.04, "Water"),
    "select all", "shade flat", "export trough.glb"])
print("wrote ground, fence, gate, tree, rock, pond, hay, trough")
